@import 'c/ihStyles';

.code {
    margin: 0;
    padding: 12px 14px;
    background: #f7f7f7;
    color: var(--ih-ink);
    border: 1px solid var(--ih-line);
    border-radius: 8px;
    font-family: 'SFMono-Regular', Consolas, 'Liberation Mono', Menlo, monospace;
    font-size: 12px;
    line-height: 1.55;
    white-space: pre-wrap;
    overflow-wrap: anywhere;
    overflow: auto;
}
.code:focus-visible {
    outline: 2px solid var(--ih-brand);
    outline-offset: 1px;
}
.code_muted {
    color: var(--ih-quiet);
}
.tk_key {
    color: #7526e3;
}
.tk_str {
    color: #056764;
}
